// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(uint256 seed) public {
        // The rule: for every admissible call, c.proxiableUUID() reports the
        // ERC-1967 implementation slot that UUPS upgrades read/write. The
        // fuzzed seed is arbitrary (no domain restriction needed) — the
        // distinguishing value is c's returned slot.
        bytes32 got = c.proxiableUUID();
        assertTrue(got == IMPLEMENTATION_SLOT);
    }
}
